.cr_sw_structure<-function(profile,pool,context){
 p<-profile;.cr_data_required(p,c('structure_id','version','currency','payment_dates','tranches','fees','initial_reserve','reserve_target','liquidity_limit','principal_mode','principal_for_interest','excess_interest_to_principal','trigger_seniority','oc_threshold','ic_threshold','terminal_policy'));for(k in c('structure_id','version','currency')) .cr_sc_text(p[[k]],k);dates<-unlist(p$payment_dates,use.names=FALSE)
 if(!length(dates)||anyDuplicated(dates)||!identical(dates,sort(dates))) .cr_error('STRUCTURED_WATERFALL','Unique ordered payment dates required');for(d in dates)if(.cr_data_date(d,'payment_date')<=.cr_data_date(pool$origin,'origin')||d>tail(pool$dates,1)[[1]]) .cr_error('STRUCTURED_CALENDAR','Payment dates must be within pool horizon after origin');if(tail(dates,1)!=tail(pool$dates,1)[[1]]) .cr_error('STRUCTURED_CALENDAR','Final pool date must be waterfall payment date')
 for(k in c('initial_reserve','reserve_target','liquidity_limit','oc_threshold','ic_threshold')) .cr_sc_number(p[[k]],k,0)
 if(!(p$principal_mode%in%c('SEQUENTIAL','PRO_RATA'))||!(p$principal_for_interest%in%c('ALWAYS','TRIGGER_ONLY','NEVER'))||!is.logical(p$excess_interest_to_principal)||length(p$excess_interest_to_principal)!=1L||is.na(p$excess_interest_to_principal)||!(p$terminal_policy%in%c('REQUIRE_COMPLETE','KEEP_OPEN'))) .cr_error('STRUCTURED_WATERFALL','Explicit supported priority and terminal conventions required')
 tranches<-.cr_data_rows(p$tranches,'tranches');ids<-vapply(tranches,function(t)t$tranche_id,'');if(!length(tranches)||anyDuplicated(ids)) .cr_error('STRUCTURED_TRANCHE','Unique nonempty tranche identities required');ranks<-numeric()
 for(t in tranches){.cr_data_required(t,c('tranche_id','seniority','notional','legal_maturity','coupon_fractions'));.cr_sc_text(t$tranche_id,'tranche_id');rank<-.cr_sc_number(t$seniority,'seniority',1);if(rank!=floor(rank)) .cr_error('STRUCTURED_TRANCHE','Integer seniority required');ranks<-c(ranks,rank);if(.cr_sc_number(t$notional,'notional',0)==0) .cr_error('STRUCTURED_TRANCHE','Positive tranche notional required');if(!(t$legal_maturity%in%dates)) .cr_error('STRUCTURED_CALENDAR','Each legal maturity must be explicit payment date');if(!is.list(t$coupon_fractions)||!setequal(names(t$coupon_fractions),dates)) .cr_error('STRUCTURED_TRANCHE','Explicit coupon fractions for every payment date required');for(d in names(t$coupon_fractions)){.cr_sc_number(t$coupon_fractions[[d]],'coupon_fraction',0);if(d>t$legal_maturity&&t$coupon_fractions[[d]]!=0) .cr_error('STRUCTURED_TRANCHE','Post-maturity interest requires separate explicit claim contract')}}
 if(anyDuplicated(ranks)||!(p$trigger_seniority%in%ranks)) .cr_error('STRUCTURED_TRANCHE','Unique seniority and existing trigger seniority required');if(!is.list(p$fees)||!setequal(names(p$fees),dates)) .cr_error('STRUCTURED_WATERFALL','Explicit additional fee schedule required');for(fee in p$fees) .cr_sc_number(fee,'fee',0);p$tranches<-tranches[order(ranks)];ctx<-.cr_result(NULL,'structured.context',context=context)$context;if(p$currency!=pool$scenario_contract$currency||(!is.null(ctx$currency)&&ctx$currency!=p$currency)||(!is.null(ctx$probability_measure)&&ctx$probability_measure!='PHYSICAL')||(!is.null(ctx$conditioning)&&ctx$conditioning!=pool$scenario_contract$conditioning)) .cr_error('TARGET_MISMATCH','Structure currency and physical scenario context must agree');horizon_days<-as.numeric(.cr_data_date(tail(dates,1),'date')-.cr_data_date(pool$origin,'origin'));if((!is.null(ctx$time_unit)&&ctx$time_unit!='days')||(!is.null(ctx$horizon)&&ctx$horizon!=horizon_days)) .cr_error('TARGET_MISMATCH','Waterfall context must use actual calendar-day horizon');list(profile=p,context=ctx)
}
run_tranche_waterfall<-function(asset_pool_paths,structure_profile,context=NULL){
 pool<-.cr_sc_checked(asset_pool_paths,'AssetPoolPaths');parsed<-.cr_sw_structure(structure_profile,pool,context);p<-parsed$profile;ctx<-parsed$context;endings<-setNames(pool$ending_states,vapply(pool$ending_states,function(e)e$scenario_id,''));if(p$terminal_policy=='REQUIRE_COMPLETE'&&any(vapply(pool$scenario_ids,function(s)!endings[[s]]$terminal_complete,TRUE))) .cr_error('STRUCTURED_UNRESOLVED','Ultimate write-down requires complete pool run-off in every scenario');keyfn<-function(s,d).cr_hash(list(s,d));by<-setNames(pool$cashflows,vapply(pool$cashflows,function(c)keyfn(c$scenario_id,c$date),''));calendar<-sort(unique(c(unlist(pool$dates,use.names=FALSE),unlist(p$payment_dates,use.names=FALSE))));tranche_rows<-accounts<-final<-list();ids<-vapply(p$tranches,function(t)t$tranche_id,'')
 for(sid in pool$scenario_ids){
 balances<-setNames(vapply(p$tranches,function(t)as.numeric(t$notional),0.),ids);arrears<-cumulative_principal<-setNames(rep(0,length(ids)),ids);timely_failure<-maturity_failure<-setNames(rep(FALSE,length(ids)),ids);reserve<-p$initial_reserve;liquidity<-interest_cash<-principal_cash<-fee_arrears<-0;pool_value<-pool$reference_principal
 for(date in calendar){
 opening_cash<-.cr_sc_sum(c(interest_cash,principal_cash,reserve));c<-by[[keyfn(sid,date)]];incoming_interest<-if(is.null(c))0 else c$interest_available;incoming_principal<-if(is.null(c))0 else .cr_sc_sum(c(c$principal_available,c$recovery_gross));cash_cost<-if(is.null(c))0 else .cr_sc_sum(c(c$workout_cost,c$servicing_cost));interest_cash<-.cr_sc_sum(c(interest_cash,incoming_interest));principal_cash<-.cr_sc_sum(c(principal_cash,incoming_principal));fee_arrears<-.cr_sc_sum(c(fee_arrears,cash_cost));if(!is.null(c))pool_value<-max(0,.cr_sc_sum(c(c$closing_performing_principal,c$pending_recovery_gross,-c$pending_workout_cost,c$closing_reinvestment_cash)))
 draws<-repayment<-fees_paid<-reserve_topup<-reserve_release<-interest_paid_total<-principal_paid_total<-equity<-0;oc_ratio<-ic_ratio<-NULL;trigger<-FALSE;terminal<-date==tail(calendar,1)&&p$terminal_policy=='REQUIRE_COMPLETE'
 if(date%in%unlist(p$payment_dates,use.names=FALSE)){
 fee_arrears<-.cr_sc_sum(c(fee_arrears,p$fees[[date]]));coupons<-setNames(vapply(p$tranches,function(t).cr_sc_sum(balances[[t$tranche_id]]*t$coupon_fractions[[date]]),0.),ids);protected<-vapply(Filter(function(t)t$seniority<=p$trigger_seniority,p$tranches),function(t)t$tranche_id,'');protected_balance<-.cr_sc_sum(balances[protected]);protected_due<-.cr_sc_sum(vapply(protected,function(t).cr_sc_sum(c(coupons[[t]],arrears[[t]])),0.));oc_numerator<-.cr_sc_sum(c(pool_value,interest_cash,principal_cash,reserve));oc_ratio<-if(protected_balance>0)oc_numerator/protected_balance else NULL;ic_ratio<-if(protected_due>0)max(0,interest_cash-fee_arrears)/protected_due else NULL;if(!is.null(oc_ratio)) .cr_sc_sum(oc_ratio);if(!is.null(ic_ratio)) .cr_sc_sum(ic_ratio);trigger<-(!is.null(oc_ratio)&&oc_ratio<p$oc_threshold)||(!is.null(ic_ratio)&&ic_ratio<p$ic_threshold);allow_principal<-p$principal_for_interest=='ALWAYS'||(p$principal_for_interest=='TRIGGER_ONLY'&&trigger)||terminal
 if(terminal){reserve_release<-reserve;principal_cash<-.cr_sc_sum(c(principal_cash,reserve));reserve<-0}
 pay_claim<-function(due,principal_allowed){paid<-min(due,interest_cash);interest_cash<<-interest_cash-paid;left<-due-paid;if(principal_allowed){take<-min(left,principal_cash);principal_cash<<-principal_cash-take;paid<-paid+take;left<-left-take};take<-min(left,reserve);reserve<<-reserve-take;paid<-paid+take;left<-left-take;take<-if(!terminal)min(left,max(0,p$liquidity_limit-liquidity))else 0;liquidity<<-.cr_sc_sum(c(liquidity,take));draws<<-.cr_sc_sum(c(draws,take));.cr_sc_sum(c(paid,take))}
 fees_paid<-pay_claim(fee_arrears,TRUE);fee_arrears<-max(0,fee_arrears-fees_paid);paid_interest<-setNames(rep(0,length(ids)),ids)
 for(t in p$tranches){tid<-t$tranche_id;due<-.cr_sc_sum(c(arrears[[tid]],coupons[[tid]]));paid<-if(fee_arrears==0)pay_claim(due,allow_principal)else 0;paid_interest[[tid]]<-paid;arrears[[tid]]<-max(0,due-paid);timely_failure[[tid]]<-timely_failure[[tid]]||arrears[[tid]]>1e-12*max(1,t$notional)}
 interest_paid_total<-.cr_sc_sum(paid_interest);repayment<-min(liquidity,.cr_sc_sum(c(interest_cash,principal_cash)));take<-min(repayment,interest_cash);interest_cash<-interest_cash-take;principal_cash<-principal_cash-(repayment-take);liquidity<-liquidity-repayment
 if(!terminal){reserve_topup<-min(max(0,p$reserve_target-reserve),interest_cash);reserve<-.cr_sc_sum(c(reserve,reserve_topup));interest_cash<-interest_cash-reserve_topup}
 if(p$excess_interest_to_principal||terminal){principal_cash<-.cr_sc_sum(c(principal_cash,interest_cash));interest_cash<-0}else{equity<-interest_cash;interest_cash<-0}
 distributable<-if(fee_arrears==0&&!any(arrears!=0))min(principal_cash,.cr_sc_sum(balances))else 0;allocations<-setNames(rep(0,length(ids)),ids)
 if(p$principal_mode=='SEQUENTIAL'||trigger){remaining<-distributable;for(t in p$tranches){tid<-t$tranche_id;allocations[[tid]]<-min(balances[[tid]],remaining);remaining<-remaining-allocations[[tid]]}}else if(distributable>0){denominator<-.cr_sc_sum(balances);for(t in p$tranches){tid<-t$tranche_id;allocations[[tid]]<-distributable*(balances[[tid]]/denominator)}}
 principal_paid_total<-.cr_sc_sum(allocations);principal_cash<-max(0,principal_cash-principal_paid_total)
 for(t in p$tranches){tid<-t$tranche_id;opening_balance<-balances[[tid]];balances[[tid]]<-max(0,opening_balance-allocations[[tid]]);cumulative_principal[[tid]]<-.cr_sc_sum(c(cumulative_principal[[tid]],allocations[[tid]]));maturity_failure[[tid]]<-maturity_failure[[tid]]||(date==t$legal_maturity&&balances[[tid]]>1e-12*max(1,t$notional));tranche_rows[[length(tranche_rows)+1L]]<-list(scenario_id=sid,date=date,tranche_id=tid,opening_principal=opening_balance,coupon_due=coupons[[tid]],interest_paid=paid_interest[[tid]],closing_interest_arrears=arrears[[tid]],principal_paid=allocations[[tid]],closing_principal=balances[[tid]],principal_write_down=if(terminal)balances[[tid]]else 0,timely_interest_failure=timely_failure[[tid]],legal_maturity_failure=maturity_failure[[tid]])}
 if(all(balances==0)&&fee_arrears==0&&!any(arrears!=0)&&liquidity==0){equity<-.cr_sc_sum(c(equity,principal_cash));principal_cash<-0}
 }
 closing_cash<-.cr_sc_sum(c(interest_cash,principal_cash,reserve));uses<-.cr_sc_sum(c(fees_paid,interest_paid_total,principal_paid_total,repayment,equity,closing_cash));residual<-.cr_sc_sum(c(opening_cash,incoming_interest,incoming_principal,draws,-uses));if(abs(residual)>1e-10*max(1,opening_cash,incoming_interest,incoming_principal)) .cr_error('STRUCTURED_CONSERVATION','Waterfall cash conservation failed');accounts[[length(accounts)+1L]]<-list(scenario_id=sid,date=date,opening_cash=opening_cash,incoming_interest=incoming_interest,incoming_principal=incoming_principal,fees_paid=fees_paid,fee_arrears=fee_arrears,interest_paid=interest_paid_total,principal_paid=principal_paid_total,liquidity_draw=draws,liquidity_repayment=repayment,liquidity_outstanding=liquidity,reserve_release=reserve_release,reserve_topup=reserve_topup,closing_reserve=reserve,closing_interest_cash=interest_cash,closing_principal_cash=principal_cash,equity_distribution=equity,oc_ratio=oc_ratio,ic_ratio=ic_ratio,trigger_breached=trigger,cash_conservation_residual=residual)
 }
 for(t in p$tranches){tid<-t$tranche_id;final[[length(final)+1L]]<-list(scenario_id=sid,tranche_id=tid,notional=t$notional,principal_paid=cumulative_principal[[tid]],remaining_principal=balances[[tid]],ultimate_principal_loss=if(p$terminal_policy=='REQUIRE_COMPLETE')balances[[tid]]else NULL,interest_arrears=arrears[[tid]],timely_interest_failure=timely_failure[[tid]],legal_maturity_failure=maturity_failure[[tid]],ultimate_identified=p$terminal_policy=='REQUIRE_COMPLETE')}
 }
 value<-.cr_sc_bound(list(schema_version='1.0',kind='TrancheWaterfallPaths',origin=pool$origin,currency=p$currency,pool_paths_hash=pool$sha256,innovation_hash=pool$innovation_hash,scenario_ids=pool$scenario_ids,scenario_weights=pool$scenario_weights,scenario_contract=pool$scenario_contract,structure_profile=p,structure_hash=.cr_hash(p),dates=as.list(calendar),tranche_cashflows=tranche_rows,cash_accounts=accounts,ending_states=final))
 .cr_result(value,'structured_credit.run_tranche_waterfall','tranche_cashflows',ctx,diagnostics=.cr_empty_object(),limitations='Configured senior additional deal fees must exclude costs already supplied by the pool. Opening reserve is external funded support; liquidity is a repayable senior claim, not credit recovery. OC uses performing principal plus pending net modeled recovery and actual cash; it is a declared contractual valuation proxy. Coupon fractions apply to opening outstanding principal; no interest on arrears or post-maturity penalty claim is invented. Triggers switch principal allocation to sequential and may permit principal-to-interest diversion. Ultimate principal write-down is identified only after explicitly complete pool run-off; legal-maturity and timely-interest failures remain separate even if subsequently cured.')
}
